DELIMITER $$
CREATE TRIGGER trg_exam_registration_before_insert BEFORE INSERT ON exam_registration FOR EACH ROW
BEGIN DECLARE v_used INT; DECLARE v_cap INT; IF NOT EXISTS(SELECT 1 FROM exam ex JOIN enrollment e ON e.offering_id=ex.offering_id WHERE ex.exam_id=NEW.exam_id AND e.enrollment_id=NEW.enrollment_id AND e.status='ENROLLED') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Active enrollment in the exam offering required'; END IF; IF fn_attendance_percentage(NEW.enrollment_id)<75 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Attendance below 75 percent'; END IF; IF NEW.exam_hall_id IS NOT NULL THEN SELECT capacity INTO v_cap FROM exam_hall WHERE exam_hall_id=NEW.exam_hall_id; SELECT COUNT(*) INTO v_used FROM exam_registration WHERE exam_id=NEW.exam_id AND exam_hall_id=NEW.exam_hall_id; IF v_used>=v_cap THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Exam hall capacity reached'; END IF; END IF; END$$
CREATE TRIGGER trg_marks_before_insert BEFORE INSERT ON marks FOR EACH ROW
BEGIN DECLARE v_max DECIMAL(5,2); DECLARE v_published TINYINT; SELECT ex.max_marks,ex.results_published INTO v_max,v_published FROM exam_registration er JOIN exam ex ON ex.exam_id=er.exam_id WHERE er.exam_registration_id=NEW.exam_registration_id; IF v_max IS NULL OR NEW.marks_obtained<0 OR NEW.marks_obtained>v_max THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Marks outside exam range'; END IF; IF v_published=1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Published marks are locked'; END IF; END$$
CREATE TRIGGER trg_marks_before_update BEFORE UPDATE ON marks FOR EACH ROW
BEGIN DECLARE v_max DECIMAL(5,2); DECLARE v_published TINYINT; SELECT ex.max_marks,ex.results_published INTO v_max,v_published FROM exam_registration er JOIN exam ex ON ex.exam_id=er.exam_id WHERE er.exam_registration_id=NEW.exam_registration_id; IF v_max IS NULL OR NEW.marks_obtained<0 OR NEW.marks_obtained>v_max THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Marks outside exam range'; END IF; IF v_published=1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Published marks are locked'; END IF; END$$
CREATE TRIGGER trg_marks_after_update AFTER UPDATE ON marks FOR EACH ROW
BEGIN IF OLD.marks_obtained<>NEW.marks_obtained THEN INSERT INTO marks_audit(marks_id,old_marks,new_marks) VALUES(NEW.marks_id,OLD.marks_obtained,NEW.marks_obtained); END IF; END$$
CREATE TRIGGER trg_revaluation_before_update BEFORE UPDATE ON revaluation_request FOR EACH ROW
BEGIN IF OLD.status<>'PENDING' AND NEW.status<>OLD.status THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Revaluation decision is final'; END IF; END$$
DELIMITER ;
